// ../src/api/routes/media.ts
var mediaRoutes = new Hono2();
mediaRoutes.get("/", async (c2) => {
  const bucket = c2.env.MEDIA_BUCKET;
  if (!bucket) {
    return c2.json({ error: "MEDIA_BUCKET no configurado" }, 500);
  }
  const listed = await bucket.list({ limit: 500 });
  const files = listed.objects.map((obj) => ({
    key: obj.key,
    size: obj.size,
    uploaded: obj.uploaded,
    url: `/media/${encodeURIComponent(obj.key)}`
  }));
  return c2.json({ files });
});
mediaRoutes.post("/", async (c2) => {
  const bucket = c2.env.MEDIA_BUCKET;
  if (!bucket) {
    return c2.json({ error: "MEDIA_BUCKET no configurado" }, 500);
  }
  const fileNameHeader = c2.req.header("X-File-Name");
  let key = fileNameHeader ? decodeURIComponent(fileNameHeader) : "upload_" + Date.now();
  key = key.replace(/^\/+/, "");
  const contentType = c2.req.header("Content-Type") || "application/octet-stream";
  const body = await c2.req.arrayBuffer();
  await bucket.put(key, body, {
    httpMetadata: { contentType }
  });
  const publicUrl = `/media/${encodeURIComponent(key)}`;
  return c2.json({
    success: true,
    file: publicUrl,
    key
  }, 201);
});
mediaRoutes.delete("/:key", async (c2) => {
  const bucket = c2.env.MEDIA_BUCKET;
  if (!bucket) {
    return c2.json({ error: "MEDIA_BUCKET no configurado" }, 500);
  }
  const key = decodeURIComponent(c2.req.param("key"));
  await bucket.delete(key);
  return c2.json({ ok: true });
});

